//! Unicode IDNA Compatibility Processing (UTS #46) for URL hosts.
//!
//! Implements ToASCII and ToUnicode with the options the URL Standard's
//! non-strict domain parser uses: CheckHyphens=false, CheckBidi=true,
//! CheckJoiners=true, UseSTD3ASCIIRules=false, Transitional_Processing=false,
//! VerifyDnsLength=false and IgnoreInvalidPunycode=false. Data comes from the
//! pinned Unicode version in [`UNICODE_VERSION`], generated by
//! `tools/generate_idna_data.py`.
//!
//! ```
//! use rustic_url::idna;
//! assert_eq!(idna::to_ascii("Bücher.example").as_deref(), Ok("xn--bcher-kva.example"));
//! let (unicode, result) = idna::to_unicode("xn--bcher-kva.example");
//! assert_eq!((unicode.as_str(), result), ("bücher.example", Ok(())));
//! ```

mod bidi;
mod mapping;
mod normalize;
mod punycode;
mod tables;
mod validity;

use std::fmt;

/// Unicode version of the IDNA mapping, normalization and property data.
pub const UNICODE_VERSION: &str = tables::UNICODE_VERSION;

/// A strong bidirectional type (Unicode Bidi_Class L, or R and AL).
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum StrongDirection {
    /// Bidi_Class L.
    Ltr,
    /// Bidi_Class R or AL.
    Rtl,
}

/// The strong bidirectional type of `value` from the pinned Bidi_Class data,
/// or `None` for weak and neutral characters.
///
/// The table is generated for IDNA's Bidi Rule; HTML directionality
/// (`dir=auto`, `:dir()`) shares it until a shared Unicode data crate exists
/// (TD-29).
///
/// ```
/// use rustic_url::idna::{StrongDirection, strong_direction};
/// assert_eq!(strong_direction('a'), Some(StrongDirection::Ltr));
/// assert_eq!(strong_direction('\u{5D0}'), Some(StrongDirection::Rtl));
/// assert_eq!(strong_direction('1'), None);
/// ```
pub fn strong_direction(value: char) -> Option<StrongDirection> {
    match bidi::bidi_class(value) {
        bidi::BidiClass::L => Some(StrongDirection::Ltr),
        bidi::BidiClass::R | bidi::BidiClass::Al => Some(StrongDirection::Rtl),
        _ => None,
    }
}

/// The first UTS #46 error recorded while processing a domain.
///
/// Errors carry no input text, so they are safe to log.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
#[non_exhaustive]
pub enum IdnaError {
    /// A code point is disallowed, or is not valid after mapping and NFC.
    DisallowedCodePoint,
    /// An `xn--` label is not ASCII, is malformed Punycode, or decodes to ASCII only.
    InvalidPunycode,
    /// A label is not NFC, starts with a combining mark or `xn--`, or contains a dot.
    InvalidLabel,
    /// A ZERO WIDTH (NON-)JOINER is outside the RFC 5892 ContextJ rules.
    ContextJ,
    /// A label of a Bidi domain name breaks the RFC 5893 Bidi Rule.
    Bidi,
    /// A label exceeds Rustic's Punycode work limit (far beyond DNS's 63 octets).
    LabelTooLong,
}

impl fmt::Display for IdnaError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(match self {
            Self::DisallowedCodePoint => "domain contains a disallowed code point",
            Self::InvalidPunycode => "domain contains an invalid Punycode label",
            Self::InvalidLabel => "domain contains an invalid label",
            Self::ContextJ => "domain uses a joiner outside its allowed context",
            Self::Bidi => "domain breaks the bidirectional label rules",
            Self::LabelTooLong => "domain label exceeds the Punycode work limit",
        })
    }
}

impl std::error::Error for IdnaError {}

impl From<punycode::PunycodeError> for IdnaError {
    fn from(error: punycode::PunycodeError) -> Self {
        match error {
            punycode::PunycodeError::Invalid => Self::InvalidPunycode,
            punycode::PunycodeError::TooLong => Self::LabelTooLong,
        }
    }
}

/// UTS #46 ToASCII. Labels with non-ASCII code points become `xn--` A-labels.
pub fn to_ascii(domain: &str) -> Result<String, IdnaError> {
    let (labels, result) = process(domain);
    result?;
    let mut output = String::with_capacity(domain.len());
    for (index, label) in labels.iter().enumerate() {
        if index > 0 {
            output.push('.');
        }
        if label.iter().all(char::is_ascii) {
            output.extend(label.iter());
        } else {
            output.push_str("xn--");
            output.push_str(&punycode::encode(label)?);
        }
    }
    Ok(output)
}

/// UTS #46 ToUnicode. The string is returned even when an error is recorded,
/// as the algorithm specifies; callers decide whether to use it.
pub fn to_unicode(domain: &str) -> (String, Result<(), IdnaError>) {
    let (labels, result) = process(domain);
    let mut output = String::with_capacity(domain.len());
    for (index, label) in labels.iter().enumerate() {
        if index > 0 {
            output.push('.');
        }
        output.extend(label.iter());
    }
    (output, result)
}

/// UTS #46 section 4 Processing; returns the Unicode labels and the first error.
fn process(domain: &str) -> (Vec<Vec<char>>, Result<(), IdnaError>) {
    let mut mapped = String::with_capacity(domain.len());
    mapping::map(domain, &mut mapped);
    let normalized = normalize::nfc(&mapped);
    let mut first_error = None;
    let mut record = |error: IdnaError| {
        first_error.get_or_insert(error);
    };
    let mut labels = Vec::new();
    for label in normalized.split('.') {
        let chars: Vec<char> = label.chars().collect();
        let Some(encoded) = label.strip_prefix("xn--") else {
            if let Err(error) = validity::check_label(&chars, false) {
                record(error);
            }
            labels.push(chars);
            continue;
        };
        if !label.is_ascii() {
            record(IdnaError::InvalidPunycode);
            labels.push(chars);
            continue;
        }
        match punycode::decode(encoded) {
            Ok(decoded) if decoded.iter().all(char::is_ascii) => {
                record(IdnaError::InvalidPunycode);
                labels.push(chars);
            }
            Ok(decoded) => {
                if let Err(error) = validity::check_label(&decoded, true) {
                    record(error);
                }
                labels.push(decoded);
            }
            Err(error) => {
                record(error.into());
                labels.push(chars);
            }
        }
    }
    if labels.iter().any(|label| bidi::is_rtl_label(label))
        && !labels.iter().all(|label| bidi::satisfies_bidi_rule(label))
    {
        record(IdnaError::Bidi);
    }
    (labels, first_error.map_or(Ok(()), Err))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn converts_common_domains() {
        assert_eq!(to_ascii("example.com").as_deref(), Ok("example.com"));
        assert_eq!(to_ascii("EXAMPLE.com.").as_deref(), Ok("example.com."));
        assert_eq!(to_ascii("faß.de").as_deref(), Ok("xn--fa-hia.de"));
        assert_eq!(to_ascii("☕.example").as_deref(), Ok("xn--53h.example"));
        assert_eq!(
            to_ascii("example.\u{625}\u{62E}\u{62A}\u{628}\u{627}\u{631}").as_deref(),
            Ok("example.xn--kgbechtv")
        );
        assert_eq!(to_ascii("a\u{3002}b").as_deref(), Ok("a.b"));
        assert_eq!(to_ascii("").as_deref(), Ok(""));
    }

    #[test]
    fn reports_errors() {
        assert_eq!(to_ascii("a\u{FFFD}"), Err(IdnaError::DisallowedCodePoint));
        // "xn--a" is well-formed Punycode for U+0080, which is disallowed.
        assert_eq!(to_ascii("xn--a"), Err(IdnaError::DisallowedCodePoint));
        assert_eq!(to_ascii("xn--9"), Err(IdnaError::InvalidPunycode));
        assert_eq!(to_ascii("xn--abc-"), Err(IdnaError::InvalidPunycode));
        assert_eq!(to_ascii("xn--te\u{161}la"), Err(IdnaError::InvalidPunycode));
        assert_eq!(to_ascii("xn--8i7caa"), Err(IdnaError::DisallowedCodePoint));
        assert_eq!(to_ascii("\u{300}a"), Err(IdnaError::InvalidLabel));
        assert_eq!(to_ascii("a\u{200C}b"), Err(IdnaError::ContextJ));
        assert_eq!(to_ascii("a.\u{5D0}").as_deref(), Ok("a.xn--4db"));
        assert_eq!(to_ascii("1.\u{5D0}"), Err(IdnaError::Bidi));
        assert_eq!(to_ascii("a.1\u{5D0}"), Err(IdnaError::Bidi));
        let long = "\u{E9}".repeat(punycode::MAX_ENCODE_INPUT + 1);
        assert_eq!(to_ascii(&long), Err(IdnaError::LabelTooLong));
    }

    #[test]
    fn to_unicode_keeps_output_on_error() {
        assert_eq!(
            to_unicode("xn--fa-hia.xn--abc-"),
            ("faß.xn--abc-".to_owned(), Err(IdnaError::InvalidPunycode))
        );
        assert_eq!(UNICODE_VERSION, "17.0.0");
    }
}
